DECLARE @bak nvarchar(500) = CAST(SERVERPROPERTY('InstanceDefaultBackupPath') AS nvarchar(400)) + N'\ModelSourcePDATA{{ModelSourceSize}}.bak';
DECLARE @dataDir nvarchar(400) = CAST(SERVERPROPERTY('InstanceDefaultDataPath') AS nvarchar(400));
DECLARE @logDir nvarchar(400) = CAST(SERVERPROPERTY('InstanceDefaultLogPath') AS nvarchar(400));
DECLARE @files TABLE (
    LogicalName nvarchar(128), PhysicalName nvarchar(260), Type char(1), FileGroupName nvarchar(128),
    Size numeric(20,0), MaxSize numeric(20,0), FileId bigint, CreateLSN numeric(25,0), DropLSN numeric(25,0),
    UniqueId uniqueidentifier, ReadOnlyLSN numeric(25,0), ReadWriteLSN numeric(25,0), BackupSizeInBytes bigint,
    SourceBlockSize int, FileGroupId int, LogGroupGUID uniqueidentifier, DifferentialBaseLSN numeric(25,0),
    DifferentialBaseGUID uniqueidentifier, IsReadOnly bit, IsPresent bit, TDEThumbprint varbinary(32), SnapshotUrl nvarchar(360));
DECLARE @disk nvarchar(600) = N'N''' + REPLACE(@bak, N'''', N'''''') + N'''';
DECLARE @sql nvarchar(max) = N'RESTORE FILELISTONLY FROM DISK = ' + @disk;
INSERT @files EXEC (@sql);
DECLARE @move nvarchar(max) = (
    SELECT STRING_AGG(CONVERT(nvarchar(max), N'MOVE N''' + REPLACE(LogicalName, N'''', N'''''') + N''' TO N'''
        + REPLACE(CASE WHEN Type = 'L' THEN @logDir ELSE @dataDir END
            + CASE WHEN RIGHT(CASE WHEN Type = 'L' THEN @logDir ELSE @dataDir END, 1) = N'\' THEN N'' ELSE N'\' END
            + N'{{$ref:connect/databases:ModelSourceDB}}' + CASE WHEN CHARINDEX(N'_', fn) > 0 THEN SUBSTRING(fn, CHARINDEX(N'_', fn), 260) ELSE N'_' + fn END, N'''', N'''''') + N''''), N', ')
    FROM (SELECT LogicalName, Type, RIGHT(PhysicalName, CHARINDEX(N'\', REVERSE(PhysicalName)) - 1) AS fn FROM @files) f);
IF DB_ID(N'{{$ref:connect/databases:ModelSourceDB}}') IS NOT NULL ALTER DATABASE [{{$ref:connect/databases:ModelSourceDB}}] SET SINGLE_USER WITH ROLLBACK IMMEDIATE;
SET @sql = N'RESTORE DATABASE [{{$ref:connect/databases:ModelSourceDB}}] FROM DISK = ' + @disk + N' WITH REPLACE, ' + @move;
EXEC (@sql);
ALTER DATABASE [{{$ref:connect/databases:ModelSourceDB}}] SET MULTI_USER;
PRINT CONCAT(N'Restored {{$ref:connect/databases:ModelSourceDB}} from ', @bak);

DECLARE @n bigint = (SELECT COUNT_BIG(*) FROM [{{$ref:connect/databases:ModelSourceDB}}].dbo.PDATA);
IF @n <> {{RecordCount}}
BEGIN
    DECLARE @msg nvarchar(400) = CONCAT(N'{{$ref:connect/databases:ModelSourceDB}}.dbo.PDATA holds ', @n, N' rows; the {{ModelSourceSize}} run needs {{RecordCount}}.');
    THROW 50005, @msg, 1;
END
PRINT CONCAT(N'{{$ref:connect/databases:ModelSourceDB}}.dbo.PDATA holds ', @n, N' rows ({{ModelSourceSize}}).');

DECLARE @actual nvarchar(256) = (SELECT JSON_VALUE([Configuration], '$.RemoteObjectName')
                                 FROM connex.tIntegrationStrategyConfiguration WHERE [Name] = N'Strategy Source Data Load');
IF @actual IS NULL
    THROW 50002, 'Strategy Source Data Load is missing on {{ProfiseeDatabaseName}}.', 1;
IF @actual <> N'{{SourceTableName}}'
BEGIN
    DECLARE @msg nvarchar(2048) = CONCAT(N'Strategy Source Data Load reads ', @actual, N' but the run size is {{SourceTableName}}. Rebuild the baseline with connect-bootstrap-main.');
    THROW 50003, @msg, 1;
END
PRINT CONCAT(N'Strategy Source Data Load reads ', @actual, N' (run size {{SourceTableName}}).');
